section "tome-cults/data/glyph_sequences/cults.lua"

t("#PURPLE#A Font of Sacrifice appears nearby!", "#PURPLE#一个牺牲之泉在周围出现了！", "_t")
t("#PURPLE#A portal appears inside the Occult Egress!", "#PURPLE#一个传送门在神秘的出口里出现了！", "_t")
